"""R-ENGINE-02 (track A of the own 3D try-on engine): the GARMENT DATA SPEC, its validator and two sample garments generated by this code.

A garment = one .glb (a single mesh whose materials are named ``base`` (required) and optionally ``trim``) + a size-chart JSON (``garment.v1``).
The .glb is the REFERENCE size only; the chart lists the measurements of every size (a table, not extra meshes). Nothing here fits a garment to a body (that is R-ENGINE-03)
and nothing here is a photo: the samples are plain tubes around the stylised base body, so they are for tests and previews, not realistic clothes.
Rights: a garment that uses a third-party asset must say so and carry ``rights_confirmed: true`` — a chart that claims a third-party asset without it is refused.
"""
from __future__ import annotations

import math
import re
import struct
from typing import Any

from app import base_models
from app.glb_tools import GlbError, build_glb, inspect_glb, parse_glb

SCHEMA = "garment.v1"
FIT_METHOD = "profile-ratio.v1"      # see app/garment_deform.py
PARTS = ("torso", "leg_l", "leg_r", "skirt", "arm_l", "arm_r")  # primitive extras {"part": ...} a fit-ready garment carries
# R-ENGINE-09: top = t-shirt body, bottom = TROUSERS (the "pants" of the request), skirt, dress (top + skirt in one piece), jacket (long-sleeved top with sleeves). One sample each.
KINDS = ("top", "bottom", "skirt", "dress", "jacket")
MAX_SIZES = 8
MAX_TRIANGLES = 50_000
MATERIALS_ALLOWED = ("base", "trim")
REQUIRED_MEASURES = {"top": ("chest_cm", "waist_cm", "length_cm"), "bottom": ("waist_cm", "hips_cm", "length_cm"), "skirt": ("waist_cm", "hips_cm", "length_cm"),
                     "dress": ("chest_cm", "waist_cm", "hips_cm", "length_cm"), "jacket": ("chest_cm", "waist_cm", "length_cm", "sleeve_cm")}
OPTIONAL_MEASURES = {"top": ("sleeve_cm",), "bottom": (), "skirt": (), "dress": (), "jacket": ()}
JACKET_EXTRA_EASE_CM = 6.0         # outerwear is cut roomier than a t-shirt
MEASURE_RANGE = (20.0, 250.0)          # cm, provisional sanity range
ID_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{1,47}$")
SIZE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9 ._-]{0,11}$")


class GarmentError(ValueError):
    """Carries every problem found, not just the first."""

    def __init__(self, problems: list[str]) -> None:
        super().__init__("; ".join(problems))
        self.problems = problems


def validate_spec(spec: Any) -> None:
    problems: list[str] = []
    if not isinstance(spec, dict):
        raise GarmentError(["spec must be an object"])
    if spec.get("schema") != SCHEMA:
        problems.append(f"schema must be {SCHEMA!r}")
    if not (isinstance(spec.get("id"), str) and ID_RE.match(spec["id"])):
        problems.append("id must be 2-48 chars of a-z 0-9 _ - starting with a letter or digit")
    kind = spec.get("kind")
    if kind not in KINDS:
        problems.append(f"kind must be one of {list(KINDS)}")
    sizes = spec.get("sizes")
    if not isinstance(sizes, dict) or not 1 <= len(sizes) <= MAX_SIZES:
        problems.append(f"sizes must be an object with 1 to {MAX_SIZES} entries")
        sizes = {}
    for label, chart in sizes.items():
        if not (isinstance(label, str) and SIZE_RE.match(label)):
            problems.append(f"size label {label!r} is not allowed")
            continue
        if not isinstance(chart, dict):
            problems.append(f"size {label}: must be an object of measurements")
            continue
        required = REQUIRED_MEASURES.get(kind, ())
        allowed = set(required) | set(OPTIONAL_MEASURES.get(kind, ()))
        for key in required:
            if key not in chart:
                problems.append(f"size {label}: missing {key}")
        for key, value in chart.items():
            if key not in allowed:
                problems.append(f"size {label}: unknown measurement {key!r}")
            elif isinstance(value, bool) or not isinstance(value, (int, float)) or not MEASURE_RANGE[0] <= float(value) <= MEASURE_RANGE[1]:
                problems.append(f"size {label}: {key} must be a number from {MEASURE_RANGE[0]:g} to {MEASURE_RANGE[1]:g}")
    ref = spec.get("reference_size")
    if ref not in sizes:
        problems.append("reference_size must be one of the sizes")
    fit = spec.get("fit")
    if fit is not None and not (isinstance(fit, dict) and fit.get("method") == FIT_METHOD and fit.get("reference_sex") in base_models.SEXES):
        problems.append(f"fit must be {{'method': {FIT_METHOD!r}, 'reference_sex': one of {list(base_models.SEXES)}}}")
    source = spec.get("source")
    if not isinstance(source, dict):
        problems.append("source must be an object")
    else:
        if not (isinstance(source.get("provenance"), str) and source["provenance"].strip()):
            problems.append("source.provenance must say where the garment came from")
        third = source.get("third_party_asset")
        if not isinstance(third, bool):
            problems.append("source.third_party_asset must be true or false")
        elif third and source.get("rights_confirmed") is not True:
            problems.append("a third-party asset needs source.rights_confirmed = true")
    if problems:
        raise GarmentError(problems)


def validate_glb(data: bytes) -> dict[str, Any]:
    try:
        doc, _ = parse_glb(data)
        info = inspect_glb(data)
    except GlbError as exc:
        raise GarmentError([f"glb: {exc}"]) from exc
    problems: list[str] = []
    if len(doc.get("meshes", [])) != 1:
        problems.append("glb must contain exactly one mesh")
    names = [m.get("name") for m in doc.get("materials", [])]
    if "base" not in names:
        problems.append("glb needs a material named 'base'")
    extra = [n for n in names if n not in MATERIALS_ALLOWED]
    if extra:
        problems.append(f"unknown material names {extra}")
    if info["triangles"] > MAX_TRIANGLES:
        problems.append(f"too many triangles ({info['triangles']} > {MAX_TRIANGLES})")
    if problems:
        raise GarmentError(problems)
    return info


def validate_garment(glb: bytes, spec: Any) -> dict[str, Any]:
    """Both parts, every problem reported. Also checks that the reference-size chart agrees with the mesh height (within 2 cm)."""
    problems: list[str] = []
    info: dict[str, Any] = {}
    for check in (lambda: validate_spec(spec), lambda: info.update(validate_glb(glb))):
        try:
            check()
        except GarmentError as exc:
            problems += exc.problems
    if not problems:
        ref = spec["sizes"][spec["reference_size"]]
        height_cm = info["size"][1] * 100
        if abs(height_cm - ref["length_cm"]) > 2.0:
            problems.append(f"reference size length_cm {ref['length_cm']} does not match the mesh height {height_cm:.1f} cm")
    if problems:
        raise GarmentError(problems)
    return {"triangles": info["triangles"], "size_m": info["size"], "kind": spec["kind"], "sizes": sorted(spec["sizes"])}


# ---- sample garments (plain tubes around the stylised base body) -------------------------------------------------------------------------------------------------

def _ring_cm(a: float, b: float) -> float:
    return round(base_models._perimeter_cm(a, b), 1)


def _write(parts: list[tuple[str, base_models._Mesh]], kind: str, colour: tuple[int, int, int]) -> bytes:
    binary = b""
    views, accessors, primitives = [], [], []
    for part, mesh in parts:
        xs, ys, zs = mesh.pos[0::3], mesh.pos[1::3], mesh.pos[2::3]
        for blob, fmt in ((struct.pack(f"<{len(mesh.pos)}f", *mesh.pos), "pos"), (struct.pack(f"<{len(mesh.idx)}H", *mesh.idx), "idx")):
            binary += b"\x00" * (-len(binary) % 4)
            views.append({"buffer": 0, "byteOffset": len(binary), "byteLength": len(blob)})
            binary += blob
        accessors += [{"bufferView": len(views) - 2, "componentType": 5126, "count": len(mesh.pos) // 3, "type": "VEC3", "min": [min(xs), min(ys), min(zs)], "max": [max(xs), max(ys), max(zs)]},
                      {"bufferView": len(views) - 1, "componentType": 5123, "count": len(mesh.idx), "type": "SCALAR"}]
        primitives.append({"attributes": {"POSITION": len(accessors) - 2}, "indices": len(accessors) - 1, "material": 0, "extras": {"part": part}})
    doc = {"asset": {"version": "2.0", "generator": "ai-creator-studio garments"}, "scene": 0, "scenes": [{"nodes": [0]}],
           "nodes": [{"name": f"sample_{kind}", "mesh": 0, "extras": {"generated_by_code": True, "garment_schema": SCHEMA, "kind": kind,
                                                                      "licence": "generated by this repository's code; no third-party asset"}}],
           "meshes": [{"name": f"sample_{kind}", "primitives": primitives}],
           "materials": [{"name": "base", "doubleSided": True, "pbrMetallicRoughness": {"baseColorFactor": [c / 255 for c in colour] + [1.0], "metallicFactor": 0.0, "roughnessFactor": 0.9}}],
           "accessors": accessors, "bufferViews": views, "buffers": [{"byteLength": len(binary)}]}
    return build_glb(doc, binary)


GARMENT_SEG = 20        # sides of a garment ring: the same as the body's, so a ring that is the body's section plus ease cannot cut into the body between two vertices


def _lerp(rows: list[tuple[float, ...]], y: float) -> tuple[float, ...]:
    """Piecewise-linear value list at height y (clamped at both ends); rows are (y, v1, v2, ...) in ascending y."""
    if y <= rows[0][0]:
        return tuple(rows[0][1:])
    if y >= rows[-1][0]:
        return tuple(rows[-1][1:])
    for lo, hi in zip(rows, rows[1:]):
        if lo[0] <= y <= hi[0]:
            t = (y - lo[0]) / (hi[0] - lo[0]) if hi[0] > lo[0] else 0.0
            return tuple(a + (b - a) * t for a, b in zip(lo[1:], hi[1:]))
    return tuple(rows[-1][1:])


def skirt_stops(p: dict[str, Any], female: bool) -> list[tuple[float, ...]]:
    """The ENVELOPE a skirt must clear, as (y, half-width, half-depth, z offset) in ascending y: from the knee-ish hem up to the waist ellipse. Where the legs are, it is wide enough to hold the hips AND
    both thighs (the depth is 1.4 x the thigh depth so that a round thigh stays inside an ellipse). Built from ``base_models.body_profiles`` (R-ENGINE-09b), the same sections the body mesh uses.
    The sample skirt is this envelope plus ease and ``app/garment_deform.py`` scales it by the ratio of the target body's envelope to the reference body's, so a skirt that stood clear stays clear."""
    profile = base_models.body_profiles(p, female)
    torso, legs, h = profile["torso"], profile["leg"], p["height"]
    waist_y, hip_y = 0.60 * h, 0.52 * h

    def env(y: float) -> tuple[float, float, float]:
        a, b, z = _lerp(torso, y)
        cx, la, lb, _ = _lerp(legs, y)
        return max(a, cx + la + 0.01), max(b, 1.4 * lb), z
    rows = [(y, *env(y)) for y in (0.34 * h, 0.43 * h, 0.47 * h, hip_y)]
    rows += [(y, *_lerp(torso, y)) for y in (0.56 * h, waist_y)]
    return rows


def build_sample_garment(kind: str, sex: str = "male", ease_cm: float = 4.0, colour: tuple[int, int, int] = (60, 90, 160),
                         measurements: dict[str, float] | None = None) -> tuple[bytes, dict[str, Any]]:
    """A plain sample garment of ``kind`` (top, bottom = trousers, skirt, dress, jacket) around the body of ``sex`` with ``ease_cm`` of room, plus its garment.v1 spec (sizes S/M/L = reference -4/0/+4 cm, a TABLE only).
    ``measurements`` (M4): make it around a body with these typed measurements instead of the preset (the garment of a size ladder is "the one made for THIS body + ease"); the chart then
    describes that garment and ``fit.reference_sex`` still names the preset used by ``garment_deform``.
    R-ENGINE-09b: every ring is the body mesh's own cross-section (``base_models.body_profiles``, including its forward/backward offsets) plus the ease, so the garment covers the body it was made for."""
    if kind not in KINDS or sex not in base_models.SEXES:
        raise ValueError("unknown kind or sex preset")
    if isinstance(ease_cm, bool) or not isinstance(ease_cm, (int, float)) or not 0.0 <= float(ease_cm) <= 20.0:
        raise ValueError("ease_cm must be a number from 0 to 20")
    p = base_models._fit_measurements(base_models.PRESETS[sex], measurements) if measurements else base_models.PRESETS[sex]
    female = sex == "female"
    h = p["height"]
    off = float(ease_cm) / 100.0 / (2 * math.pi)     # radial offset giving about ease_cm more perimeter
    hip_y, waist_y, chest_y, shoulder_y = 0.52 * h, 0.60 * h, 0.70 * h, 0.81 * h
    profile = base_models.body_profiles(p, female)
    torso = profile["torso"]

    def mesh() -> base_models._Mesh:
        m = base_models._Mesh()
        m.seg = GARMENT_SEG
        return m

    def ring(centre_x: float, y: float, a: float, b: float, z: float = 0.0, extra: float = 0.0) -> tuple[tuple[float, float, float], float, float]:
        return ((centre_x, y, z), a + off + extra, b + off + extra)

    def torso_rings(y_from: float, y_to: float, extra: float = 0.0):
        return [ring(0.0, y, a, b, z, extra) for y, a, b, z in torso if y_from - 1e-9 <= y <= y_to + 1e-9]

    def torso_ring_at(y: float, extra: float = 0.0):
        return min(torso_rings(0.0, 9.0, extra), key=lambda r: abs(r[0][1] - y))

    def leg_rings(side: int):
        return [ring(side * cx, y, a, b, z) for y, cx, a, b, z in reversed(profile["leg"]) if 0.04 * h - 1e-9 <= y <= hip_y + 1e-9]
    if kind == "top":
        stops = torso_rings(hip_y, shoulder_y)
        torso_mesh = mesh()
        torso_mesh.tube(stops, cap=False)
        parts = [("torso", torso_mesh)]
        chest, waist = torso_ring_at(chest_y), torso_ring_at(waist_y)
        measures = {"chest_cm": _ring_cm(chest[1], chest[2]), "waist_cm": _ring_cm(waist[1], waist[2]), "length_cm": round((shoulder_y - hip_y) * 100, 1)}
    elif kind == "bottom":
        torso_mesh = mesh()
        torso_mesh.tube(torso_rings(torso[0][0], waist_y), cap=False)         # down to the crotch, so the pelvis is covered between the legs
        parts = [("torso", torso_mesh)]
        for side in (-1, 1):
            leg = mesh()
            parts.append(("leg_l" if side == -1 else "leg_r", leg))
            leg.tube(leg_rings(side), cap=False)
        hip, waist = torso_ring_at(hip_y), torso_ring_at(waist_y)
        measures = {"waist_cm": _ring_cm(waist[1], waist[2]), "hips_cm": _ring_cm(hip[1], hip[2]), "length_cm": 0.0}
    elif kind in ("skirt", "dress"):
        env = skirt_stops(p, female)                                # ascending y: knee-ish hem ... waist
        skirt = mesh()
        skirt.tube([ring(0.0, y, a, b, z) for y, a, b, z in env[::-1]], cap=False)    # rings from the waist down to the hem
        parts = [("skirt", skirt)]
        hip = ring(0.0, hip_y, *env[3][1:3], env[3][3])
        waist = torso_ring_at(waist_y)
        measures = {"waist_cm": _ring_cm(waist[1], waist[2]), "hips_cm": _ring_cm(hip[1], hip[2]), "length_cm": 0.0}
        if kind == "dress":
            torso_mesh = mesh()
            upper = torso_rings(waist_y, shoulder_y)
            torso_mesh.tube(upper[::-1], cap=False)
            parts = [("torso", torso_mesh), ("skirt", skirt)]
            chest = torso_ring_at(chest_y)
            measures["chest_cm"] = _ring_cm(chest[1], chest[2])
    else:                                                           # jacket: a roomier top that also covers both arms down to the wrist
        extra = JACKET_EXTRA_EASE_CM / 100.0 / (2 * math.pi)
        first = torso[0][0]
        torso_mesh = mesh()
        torso_mesh.tube(torso_rings(first, shoulder_y, extra), cap=False)
        parts = [("torso", torso_mesh)]
        arm = profile["arm"]                                        # wrist -> shoulder cap top, ascending y
        for side in (-1, 1):
            sleeve = mesh()
            parts.append(("arm_l" if side == -1 else "arm_r", sleeve))
            sleeve.tube([ring(side * cx, y, a, b, z, extra) for y, cx, a, b, z in arm], cap=False)
        path = [(row[1], row[0]) for row in arm if row[0] <= shoulder_y - 0.02]         # (x, y) from the wrist up to the top of the upper arm
        sleeve_cm = sum(math.hypot(path[i][0] - path[i + 1][0], path[i][1] - path[i + 1][1]) for i in range(len(path) - 1)) * 100
        chest, waist = torso_ring_at(chest_y, extra), torso_ring_at(waist_y, extra)
        measures = {"chest_cm": _ring_cm(chest[1], chest[2]), "waist_cm": _ring_cm(waist[1], waist[2]), "length_cm": 0.0, "sleeve_cm": round(sleeve_cm, 1)}
    glb = _write(parts, kind, colour)
    # the chart's length_cm is the height the mesh really has (a bottom runs from the waist down to the ankles), so chart and mesh cannot disagree
    real_cm = round(inspect_glb(glb)["size"][1] * 100, 1)
    measures["length_cm"] = real_cm
    chart = {"M": dict(measures)}
    for label, delta in (("S", -4.0), ("L", 4.0)):
        chart[label] = {key: (round(value + delta, 1) if key != "length_cm" else value) for key, value in measures.items()}
    spec = {"schema": SCHEMA, "id": f"sample-{kind}-{sex}", "kind": kind, "reference_size": "M", "sizes": chart,
            "fit": {"method": FIT_METHOD, "reference_sex": sex},
            "source": {"provenance": "generated by this repository's code (app/garments.py build_sample_garment)", "third_party_asset": False, "rights_confirmed": True}}
    return glb, spec
